  // Form State
  const [formData, setFormData] = useState({
    platforms: [] as string[],
    languages: [] as string[],
    markets: [] as string[],
    industry: '',
    industryOther: '',
    hasPayments: null as boolean | null,
    hasExistingBusiness: null as boolean | null,
    serviceModel: '',
    closestApp: '',
    name: '',
    brandColor: '#1DB7F0',
    description: '', // Generated later

    // Signup Data
