/**
 * CLOUD FUNCTION REFERENCE
 * Deploy this to Firebase Cloud Functions to enable background notifications.
 * 
 * Dependencies: firebase-admin, firebase-functions
 */

const functions = require("firebase-functions");
const admin = require("firebase-admin");
admin.initializeApp();

exports.sendChatNotification = functions.firestore
  .document("conversations/{conversationId}/messages/{messageId}")
  .onCreate(async (snap, context) => {
    const newMessage = snap.data();
    const conversationId = context.params.conversationId;

    // Only notify if message is from STAFF (support) to USER
    if (newMessage.sender !== "staff") {
      return null;
    }

    // Get the user ID from the conversation ID (assuming conversationId == userId)
    const userId = conversationId;

    // 1. Increment Unread Counter on User Document
    try {
      await admin.firestore().collection("users").doc(userId).update({
        chatUnreadCount: admin.firestore.FieldValue.increment(1)
      });
    } catch (e) {
      console.log("Failed to increment user unread count", e);
      // Continue to send notification even if counter update fails
    }

    // 2. Send Push Notification
    // Retrieve user's FCM tokens from Firestore
    // Assumption: Tokens are stored in users/{userId}/fcmTokens or similar
    const userDoc = await admin.firestore().collection("users").doc(userId).get();
    const userData = userDoc.data();

    if (!userData || !userData.fcmTokens || userData.fcmTokens.length === 0) {
      console.log("No tokens for user", userId);
      return null;
    }

    const payload = {
      notification: {
        title: newMessage.senderName || "New Message",
        body: newMessage.text || "You have a new message from support.",
        sound: "default", // Or custom sound filename if uploaded to Android/iOS bundle
      },
      data: {
        conversationId: conversationId,
        click_action: "FLUTTER_NOTIFICATION_CLICK" // or web URL
      },
    };

    // Send to all tokens
    const response = await admin.messaging().sendToDevice(userData.fcmTokens, payload);

    // Cleanup invalid tokens
    const tokensToRemove = [];
    response.results.forEach((result, index) => {
      const error = result.error;
      if (error) {
        if (error.code === "messaging/invalid-registration-token" ||
            error.code === "messaging/registration-token-not-registered") {
          tokensToRemove.push(userData.fcmTokens[index]);
        }
      }
    });

    if (tokensToRemove.length > 0) {
      await admin.firestore().collection("users").doc(userId).update({
        fcmTokens: admin.firestore.FieldValue.arrayRemove(...tokensToRemove)
      });
    }

    return console.log("Notification sent successfully");
  });

exports.createGuestAppointment = functions.region('us-central1').https.onCall(async (data, context) => {
  try {
    // 0. Safety Check
    if (!data) {
      throw new functions.https.HttpsError('invalid-argument', 'No data provided.');
    }

    const { guestName, guestPhone, guestEmail, dateKey, time, topic, notes } = data;

    // 1. Validate Input
    if (!guestName || !guestPhone || !dateKey || !time) {
      throw new functions.https.HttpsError('invalid-argument', 'Missing required fields.');
    }

    const db = admin.firestore();

    // 2. Get Global Settings for Duration
    let durationMin = 30;
    try {
      const settingsSnap = await db.collection('appointment_settings').doc('global').get();
      if (settingsSnap.exists) {
        durationMin = settingsSnap.data().durationMin || 30;
      }
    } catch (e) {
      console.error("Failed to fetch settings, using default duration.", e);
    }

    // 3. Calculate Timestamps
    const isoString = `${dateKey}T${time}:00+03:00`;
    const startAtDate = new Date(isoString);

    if (isNaN(startAtDate.getTime())) {
      throw new functions.https.HttpsError('invalid-argument', 'Invalid date/time format.');
    }

    const startAtMs = startAtDate.getTime();
    const endAtMs = startAtMs + (durationMin * 60 * 1000);

    const startAtTimestamp = admin.firestore.Timestamp.fromMillis(startAtMs);
    const endAtTimestamp = admin.firestore.Timestamp.fromMillis(endAtMs);

    // 4. Check for Conflicts
